-- Bank soal per kitab: 1 modul = 1 level, 8 soal, kunci per jalur.
-- Sumber: modul, contoh, dan glosarium kitab curated/fondasi.
-- Idempoten. Modul intro 3 soal diganti jalur level rapi.

PRAGMA foreign_keys = ON;

