UPDATE learn_modul SET is_aktif = 0 WHERE id IN ('learn-quran-tahsin-01','learn-aqidah-aswaja-01','learn-adab-01','learn-fikih-praktis-01','learn-hadits-01');

INSERT OR IGNORE INTO learn_modul (id, lembaga_id, path_key, judul, deskripsi, kategori, urutan, is_aktif) VALUES
  ('kitab-tajwid-l01', NULL, 'quran_tahsin', 'Level 1 · Pelajaran Pendahuluan dan Bunyi Huruf', 'Definisi ilmu tajwid, tujuan mempelajarinya, huruf hijaiyah, dan harakat dasar.', 'kitab', 1, 1),
  ('kitab-tajwid-l02', NULL, 'quran_tahsin', 'Level 2 · Nun Sukun dan Tanwin I', 'Izhar halqi dan idgham bighunnah.', 'kitab', 2, 1),
  ('kitab-tajwid-l03', NULL, 'quran_tahsin', 'Level 3 · Nun Sukun dan Tanwin II', 'Idgham bilaghunnah, iqlab, dan ikhfa haqiqi.', 'kitab', 3, 1),
  ('kitab-tajwid-l04', NULL, 'quran_tahsin', 'Level 4 · Mim Sukun, Ghunnah, dan Macam Idgham', 'Idhar syafawi, ikhfa syafawi, idgham mimi, mim dan nun tasydid, serta pengantar idgham mutamatsilain.', 'kitab', 4, 1),
  ('kitab-tajwid-l05', NULL, 'quran_tahsin', 'Level 5 · Lam Ta''rif, Qalqalah, dan Huruf Tebal-Tipis', 'Lam qamariyah, lam syamsiyah, qalqalah, ra'', dan lafzul jalalah.', 'kitab', 5, 1),
  ('kitab-tajwid-l06', NULL, 'quran_tahsin', 'Level 6 · Bab Mad dan Adab Berhenti', 'Mad asli, mad far''i yang sering muncul, dan kebiasaan berhenti yang aman untuk pemula.', 'kitab', 6, 1),
  ('kitab-aqidah-l01', NULL, 'aqidah_aswaja', 'Level 1 · Muqaddimah Tauhid dan Kalimat Syahadat', 'Makna aqidah, mengapa tauhid dipelajari, dan posisi syahadat sebagai pintu iman.', 'kitab', 1, 1),
  ('kitab-aqidah-l02', NULL, 'aqidah_aswaja', 'Level 2 · Sifat Nafsiyyah dan Salbiyyah', 'Wujud, qidam, baqa, mukhalafatuhu lil hawadits, qiyamuhu binafsih, dan wahdaniyyah.', 'kitab', 2, 1),
  ('kitab-aqidah-l03', NULL, 'aqidah_aswaja', 'Level 3 · Sifat Ma''ani', 'Qudrat, iradat, ilmu, hayat, sama'', basar, dan kalam.', 'kitab', 3, 1),
  ('kitab-aqidah-l04', NULL, 'aqidah_aswaja', 'Level 4 · Sifat Ma''nawiyyah dan Adab Tanzih', 'Kaunuhu qadiran dan kawan-kawannya, serta menjaga keyakinan agar tidak menyerupakan Allah dengan makhluk.', 'kitab', 4, 1),
  ('kitab-aqidah-l05', NULL, 'aqidah_aswaja', 'Level 5 · Sifat Wajib, Mustahil, dan Jaiz bagi Rasul', 'Shiddiq, amanah, tabligh, fathanah, serta lawan-lawan sifat tersebut.', 'kitab', 5, 1),
  ('kitab-aqidah-l06', NULL, 'aqidah_aswaja', 'Level 6 · Sam''iyyat dan Rukun Iman', 'Iman kepada malaikat, kitab, rasul, hari akhir, dan qada qadar.', 'kitab', 6, 1),
  ('kitab-aqidah-l07', NULL, 'aqidah_aswaja', 'Level 7 · Cinta Nabi, Keluarga, Sahabat, dan Adab Menjaga Iman', 'Shalawat, hormat kepada Ahlul Bait dan sahabat, serta penjagaan iman dalam kebiasaan harian.', 'kitab', 7, 1),
  ('kitab-fiqih-l01', NULL, 'fikih_praktis', 'Level 1 · Mukadimah Iman, Islam, dan Tanda Baligh', 'Rukun iman, rukun Islam, dan pengantar taklif sebelum masuk ke bab thaharah.', 'kitab', 1, 1),
  ('kitab-fiqih-l02', NULL, 'fikih_praktis', 'Level 2 · Istinja, Niat, dan Adab Bersuci', 'Syarat istinja, pengertian niat, dan awal pembiasaan thaharah.', 'kitab', 2, 1),
  ('kitab-fiqih-l03', NULL, 'fikih_praktis', 'Level 3 · Mandi Wajib, Hadas Besar, dan Wudhu', 'Sebab mandi, fardu wudhu, sunnah wudhu, dan larangan bagi orang berhadas.', 'kitab', 3, 1),
  ('kitab-fiqih-l04', NULL, 'fikih_praktis', 'Level 4 · Tayammum, Najis, dan Darah Kebiasaan', 'Sebab tayammum, syarat-syaratnya, jenis najis, serta pengantar haid dan nifas.', 'kitab', 4, 1),
  ('kitab-fiqih-l05', NULL, 'fikih_praktis', 'Level 5 · Syarat dan Rukun Shalat', 'Niat, takbir, Al-Fatihah, ruku'', sujud, tasyahhud, dan bacaan pokok shalat.', 'kitab', 5, 1),
  ('kitab-fiqih-l06', NULL, 'fikih_praktis', 'Level 6 · Waktu Shalat, Jamaah, dan Makmum', 'Awal waktu shalat, syarat berjamaah, syarat makmum, dan dasar jama'' ta''khir.', 'kitab', 6, 1),
  ('kitab-fiqih-l07', NULL, 'fikih_praktis', 'Level 7 · Jumat, Khutbah, dan Fiqih Jamaah Umum', 'Syarat Jumat, dua khutbah, dan kesiapan menghadiri ibadah bersama masyarakat.', 'kitab', 7, 1),
  ('kitab-fiqih-l08', NULL, 'fikih_praktis', 'Level 8 · Puasa, Haji, dan Janazah', 'Pembatal puasa, pengantar ibadah haji, memandikan mayat, dan shalat jenazah.', 'kitab', 8, 1),
  ('kitab-hadits-l01', NULL, 'hadits', 'Level 1 · Hadits Niat dan Ikhlas', 'Hadits pertama tentang niat sebagai pondasi amal dan belajar.', 'kitab', 1, 1),
  ('kitab-hadits-l02', NULL, 'hadits', 'Level 2 · Hadits Jibril tentang Islam, Iman, dan Ihsan', 'Hadits kedua sebagai peta besar agama.', 'kitab', 2, 1),
  ('kitab-hadits-l03', NULL, 'hadits', 'Level 3 · Rukun Islam sebagai Tiang Amal', 'Hadits tentang Islam dibangun di atas lima perkara.', 'kitab', 3, 1),
  ('kitab-hadits-l04', NULL, 'hadits', 'Level 4 · Penciptaan Manusia, Takdir, dan Husnul Khatimah', 'Hadits tentang proses penciptaan, ketetapan amal, dan penutup hidup.', 'kitab', 4, 1),
  ('kitab-hadits-l05', NULL, 'hadits', 'Level 5 · Menolak Bid''ah dan Amal yang Menyimpang', 'Hadits tentang tertolaknya perkara baru yang tidak berasal dari agama.', 'kitab', 5, 1),
  ('kitab-hadits-l06', NULL, 'hadits', 'Level 6 · Halal, Haram, dan Syubhat', 'Hadits tentang kejelasan halal dan haram serta pentingnya wara''.', 'kitab', 6, 1),
  ('kitab-hadits-l07', NULL, 'hadits', 'Level 7 · Nasihat, Kehormatan Muslim, dan Kemampuan Menjalankan Syariat', 'Hadits tentang agama adalah nasihat, kehormatan seorang muslim, dan tugas agama sesuai kemampuan.', 'kitab', 7, 1),
  ('kitab-hadits-l08', NULL, 'hadits', 'Level 8 · Rezeki yang Baik dan Cinta Sesama Muslim', 'Hadits tentang Allah yang Mahabaik, rezeki halal, dan iman yang mendorong cinta kepada sesama.', 'kitab', 8, 1),
  ('kitab-adab-l01', NULL, 'adab', 'Level 1 · Niat Mencari Ilmu dan Peta Hidayah', 'Pengantar penyusun tentang niat, tujuan ilmu, dan bahaya mencari ilmu untuk popularitas.', 'kitab', 1, 1),
  ('kitab-adab-l02', NULL, 'adab', 'Level 2 · Bangun Tidur, Kamar Kecil, dan Adab Awal Hari', 'Rutinitas pagi: doa bangun tidur, adab masuk kamar kecil, istinja, dan siwak.', 'kitab', 2, 1),
  ('kitab-adab-l03', NULL, 'adab', 'Level 3 · Wudhu, Mandi, Tayammum, dan Kebersihan Lahir', 'Adab bersuci yang detail sebagai pintu semua ibadah.', 'kitab', 3, 1),
  ('kitab-adab-l04', NULL, 'adab', 'Level 4 · Pergi ke Masjid dan Adab Melaksanakan Shalat', 'Adab menuju masjid, masuk masjid, persiapan shalat, imam-makmum, dan suasana ibadah.', 'kitab', 4, 1),
  ('kitab-adab-l05', NULL, 'adab', 'Level 5 · Amalan Siang-Malam, Jumat, Puasa, dan Menjelang Tidur', 'Wirid harian dan pembiasaan ibadah yang menyelimuti seluruh waktu.', 'kitab', 5, 1),
  ('kitab-adab-l06', NULL, 'adab', 'Level 6 · Menjaga Mata, Telinga, dan Lisan', 'Larangan lahiriyah yang paling sering merusak hati.', 'kitab', 6, 1),
  ('kitab-adab-l07', NULL, 'adab', 'Level 7 · Menjaga Perut, Farj, Tangan, Kaki, dan Penyakit Hati', 'Pengendalian nafsu lahir serta larangan ujub, takabur, dan merasa lebih baik dari orang lain.', 'kitab', 7, 1),
  ('kitab-adab-l08', NULL, 'adab', 'Level 8 · Adab dengan Allah, Guru, Murid, Orang Tua, dan Sesama', 'Bab penutup tentang sopan santun pergaulan dan penataan hubungan.', 'kitab', 8, 1),
  ('kitab-arab1-l01', NULL, 'arabic_kitab_1', 'Level 1 · Fondasi Bunyi dan Tanda Baca', 'Fondasi Bunyi dan Tanda Baca', 'nahwu', 1, 1),
  ('kitab-arab1-l02', NULL, 'arabic_kitab_1', 'Level 2 · Menunjuk Benda dan Orang', 'Isim isyarah dasar untuk benda dekat dan jauh.', 'nahwu', 2, 1),
  ('kitab-arab1-l03', NULL, 'arabic_kitab_1', 'Level 3 · Huruf Jar dan Keterangan Tempat', 'في، على، من، إلى، أين dan perubahan akhir kata setelah huruf jar.', 'nahwu', 3, 1),
  ('kitab-arab1-l04', NULL, 'arabic_kitab_1', 'Level 4 · Idhafah dan Kepemilikan', 'Mudhaf-mudhaf ilaih, لي, عندي, هل عندك؟', 'nahwu', 4, 1),
  ('kitab-arab1-l05', NULL, 'arabic_kitab_1', 'Level 5 · Mudzakkar, Muannats, dan Sifat', 'Keserasian gender dan sifat dalam kalimat nominal.', 'nahwu', 5, 1),
  ('kitab-arab1-l06', NULL, 'arabic_kitab_1', 'Level 6 · Dhamir Milik yang Menempel', 'كتابك، كتابه، كتابها، كتابي dan penekanan sederhana.', 'nahwu', 6, 1),
  ('kitab-arab1-l07', NULL, 'arabic_kitab_1', 'Level 7 · Jamak dan Murajaah Pola Dasar', 'Jamak salim, jamak taksir, هؤلاء, هم, dan rangkuman tematik.', 'nahwu', 7, 1),
  ('kitab-arab2-l01', NULL, 'arabic_kitab_2', 'Level 1 · Peta Kalimat dan Partikel Awal', 'Jumlah ismiyyah, jumlah fi''liyyah, dan partikel pembuka makna.', 'nahwu', 1, 1),
  ('kitab-arab2-l02', NULL, 'arabic_kitab_2', 'Level 2 · Negasi dan Perbandingan', 'لَيْسَ, kalimat negatif nominal, dan isim tafdhil.', 'nahwu', 2, 1),
  ('kitab-arab2-l03', NULL, 'arabic_kitab_2', 'Level 3 · Bilangan 11-20 dan Kesesuaian Jenis', 'Bilangan belasan, ma''dud, dan gender maskulin-feminin.', 'nahwu', 3, 1),
  ('kitab-arab2-l04', NULL, 'arabic_kitab_2', 'Level 4 · Fi''il Madhi dan Perubahan Subjek', 'Fi''il madhi, dhamir pelaku, dan bentuk negatif lampau.', 'nahwu', 4, 1),
  ('kitab-arab2-l05', NULL, 'arabic_kitab_2', 'Level 5 · Fa''il dan Maf''ul Bih', 'Subjek kalimat verbal, objek langsung, dan arah makna tindakan.', 'nahwu', 5, 1),
  ('kitab-arab2-l06', NULL, 'arabic_kitab_2', 'Level 6 · Fi''il Mudhari dan Konjugasi Dasar', 'Makna sedang-akan, tasrif mudhari, dan pengenalan perubahan i''rab.', 'nahwu', 6, 1),
  ('kitab-arab2-l07', NULL, 'arabic_kitab_2', 'Level 7 · Amr, Nahi, dan Ungkapan Keinginan', 'Perintah, larangan, dan pola ingin/berharap dengan fi''il sesudahnya.', 'nahwu', 7, 1),
  ('kitab-arab2-l08', NULL, 'arabic_kitab_2', 'Level 8 · Dual, Jamak, dan Tanda I''rab Lanjutan', 'Mutsanna, jamak, pengantar kana, dan jalan masuk ke fi''il lemah.', 'nahwu', 8, 1),
  ('kitab-arab3-l01', NULL, 'arabic_kitab_3', 'Level 1 · I''rab Isim dan Fi''il', 'Mu''rab, mabni, rafa'', nashab, jarr, dan jazm.', 'nahwu', 1, 1),
  ('kitab-arab3-l02', NULL, 'arabic_kitab_3', 'Level 2 · Waw, Penghubung, dan Arah Makna', 'Fungsi waw dan partikel penghubung dalam kalimat.', 'nahwu', 2, 1),
  ('kitab-arab3-l03', NULL, 'arabic_kitab_3', 'Level 3 · Kalimat Aktif dan Pasif', 'Fi''il mabni lil ma''lum dan mabni lil majhul.', 'nahwu', 3, 1),
  ('kitab-arab3-l04', NULL, 'arabic_kitab_3', 'Level 4 · Ism Fa''il dan Ism Maf''ul', 'Pelaku, yang dikenai pekerjaan, dan pola turunan dari fi''il.', 'nahwu', 4, 1),
  ('kitab-arab3-l05', NULL, 'arabic_kitab_3', 'Level 5 · Ism Zaman, Ism Makan, dan Ism Alat', 'Kata benda waktu, tempat, dan alat yang lahir dari fi''il.', 'nahwu', 5, 1),
  ('kitab-arab3-l06', NULL, 'arabic_kitab_3', 'Level 6 · Ma''rifah, Nakirah, dan Susunan Nominal Lanjutan', 'Ketentuan kata, idhafah, penghilangan nun, dan bentuk penunjuk.', 'nahwu', 6, 1),
  ('kitab-arab3-l07', NULL, 'arabic_kitab_3', 'Level 7 · Zharf, Syarth, dan Istifham', 'Keterangan waktu-tempat, kalimat syarat, dan kata tanya.', 'nahwu', 7, 1),
  ('kitab-arab3-l08', NULL, 'arabic_kitab_3', 'Level 8 · Enam Bab Tsulatsi dan Pintu ke Bab Af''ala', 'Kelompok fi''il tsulatsi mujarrad, masdar, dan pengantar fi''il mazid.', 'nahwu', 8, 1),
  ('kitab-arab4-l01', NULL, 'arabic_kitab_4', 'Level 1 · Fi''il Transitif dan Intransitif', 'Muta''addi, lazim, objek langsung, dan objek tak langsung.', 'nahwu', 1, 1),
  ('kitab-arab4-l02', NULL, 'arabic_kitab_4', 'Level 2 · Membuat Fi''il Lazim Menjadi Aktif-Causative', 'Af''ala, tasydid, intensitas, dan pemindahan aksi.', 'nahwu', 2, 1),
  ('kitab-arab4-l03', NULL, 'arabic_kitab_4', 'Level 3 · Bab Faa''ala dan Jaringan Makna Turunan', 'Makna saling, proses, dan pola turunan dari fi''il mazid.', 'nahwu', 3, 1),
  ('kitab-arab4-l04', NULL, 'arabic_kitab_4', 'Level 4 · Bab Tafa''ala dan Tafa''''ala', 'Makna bertahap, refleksif, dibuat-buat, atau proses internal.', 'nahwu', 4, 1),
  ('kitab-arab4-l05', NULL, 'arabic_kitab_4', 'Level 5 · Bab Infa''ala dan Ifta''ala', 'Makna menerima pengaruh, berubah, atau masuk ke suatu keadaan.', 'nahwu', 5, 1),
  ('kitab-arab4-l06', NULL, 'arabic_kitab_4', 'Level 6 · Jenis-Jenis Dhamir', 'Dhamir bariz, mustatir, muttashil, dan rujukan kata dalam paragraf.', 'nahwu', 6, 1),
  ('kitab-arab4-l07', NULL, 'arabic_kitab_4', 'Level 7 · Maf''ul Lanjutan dan Penekanan', 'Maf''ul mutlaq, maf''ul lahu, maf''ul ma''ahu, taukid, dan badal.', 'nahwu', 7, 1),
  ('kitab-arab4-l08', NULL, 'arabic_kitab_4', 'Level 8 · Struktur Lanjutan dan Murajaah Penutup', 'La nafiyah lil jins, syarth, warna-cacat, pola jamak, dan bacaan lanjutan.', 'nahwu', 8, 1);

INSERT OR IGNORE INTO learn_soal (
  id, modul_id, tipe, pertanyaan, pilihan, pilihan_a, pilihan_b, pilihan_c, pilihan_d,
  jawaban_benar, penjelasan, urutan
) VALUES
  ('kitab-tajwid-l01-q01', 'kitab-tajwid-l01', 'pilihan_ganda', 'Apa arti dari بَ - تَ - ثَ?', '["latihan bunyi huruf yang berdekatan", "contoh kata yang menuntut kejelasan bunyi huruf dan harakat", "membaca nun sukun atau tanwin dengan jelas karena bertemu huruf halqi", "memasukkan bunyi nun sukun atau tanwin dengan dengung"]', 'latihan bunyi huruf yang berdekatan', 'contoh kata yang menuntut kejelasan bunyi huruf dan harakat', 'membaca nun sukun atau tanwin dengan jelas karena bertemu huruf halqi', 'memasukkan bunyi nun sukun atau tanwin dengan dengung', 'a', 'بَ - تَ - ثَ dalam level ini bermakna: latihan bunyi huruf yang berdekatan.', 1),
  ('kitab-tajwid-l01-q02', 'kitab-tajwid-l01', 'pilihan_ganda', 'Mana contoh yang bermakna «latihan bunyi huruf yang berdekatan»?', '["idgham bighunnah", "الْحَمْدُ", "izhar halqi", "بَ - تَ - ثَ"]', 'idgham bighunnah', 'الْحَمْدُ', 'izhar halqi', 'بَ - تَ - ثَ', 'd', 'Contoh yang tepat adalah بَ - تَ - ثَ.', 2),
  ('kitab-tajwid-l01-q03', 'kitab-tajwid-l01', 'pilihan_ganda', 'Apa arti dari الْحَمْدُ?', '["latihan bunyi huruf yang berdekatan", "contoh kata yang menuntut kejelasan bunyi huruf dan harakat", "membaca nun sukun atau tanwin dengan jelas karena bertemu huruf halqi", "memasukkan bunyi nun sukun atau tanwin dengan dengung"]', 'latihan bunyi huruf yang berdekatan', 'contoh kata yang menuntut kejelasan bunyi huruf dan harakat', 'membaca nun sukun atau tanwin dengan jelas karena bertemu huruf halqi', 'memasukkan bunyi nun sukun atau tanwin dengan dengung', 'b', 'الْحَمْدُ dalam level ini bermakna: contoh kata yang menuntut kejelasan bunyi huruf dan harakat.', 3),
  ('kitab-tajwid-l01-q04', 'kitab-tajwid-l01', 'pilihan_ganda', 'Mana contoh yang bermakna «contoh kata yang menuntut kejelasan bunyi huruf dan harakat»?', '["الْحَمْدُ", "بَ - تَ - ثَ", "izhar halqi", "idgham bighunnah"]', 'الْحَمْدُ', 'بَ - تَ - ثَ', 'izhar halqi', 'idgham bighunnah', 'a', 'Contoh yang tepat adalah الْحَمْدُ.', 4),
  ('kitab-tajwid-l01-q05', 'kitab-tajwid-l01', 'pilihan_ganda', 'Fokus utama Level 1 adalah?', '["Ilmu tajwid menjaga lisan dari kesalahan membaca Al-Qur''an.", "Bagian awal ini merapikan pondasi. Santri tidak langsung dibebani istilah cabang, tetapi diajak paham dulu apa itu tajwid, mengapa bacaan harus dijaga, serta bagaimana huruf dan harakat membentuk bunyi yang benar.", "Definisi ilmu tajwid, tujuan mempelajarinya, huruf hijaiyah, dan harakat dasar.", "Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara."]', 'Ilmu tajwid menjaga lisan dari kesalahan membaca Al-Qur''an.', 'Bagian awal ini merapikan pondasi. Santri tidak langsung dibebani istilah cabang, tetapi diajak paham dulu apa itu tajwid, mengapa bacaan harus dijaga, serta bagaimana huruf dan harakat membentuk bunyi yang benar.', 'Definisi ilmu tajwid, tujuan mempelajarinya, huruf hijaiyah, dan harakat dasar.', 'Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara.', 'c', 'Level ini fokus pada: Definisi ilmu tajwid, tujuan mempelajarinya, huruf hijaiyah, dan harakat dasar.', 5),
  ('kitab-tajwid-l01-q06', 'kitab-tajwid-l01', 'pilihan_ganda', 'Pilih pernyataan yang paling tepat dari pelajaran ini.', '["Bagian awal ini merapikan pondasi. Santri tidak langsung dibebani istilah cabang, tetapi diajak paham dulu apa itu tajwid, mengapa bacaan harus dijaga, serta bagaimana huruf dan harakat membentuk bunyi yang benar.", "Ilmu tajwid menjaga lisan dari kesalahan membaca Al-Qur''an.", "Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara.", "Latihan dasar harus dimulai dari ketelitian mendengar dan menirukan bacaan, bukan terburu-buru mengejar banyak hukum."]', 'Bagian awal ini merapikan pondasi. Santri tidak langsung dibebani istilah cabang, tetapi diajak paham dulu apa itu tajwid, mengapa bacaan harus dijaga, serta bagaimana huruf dan harakat membentuk bunyi yang benar.', 'Ilmu tajwid menjaga lisan dari kesalahan membaca Al-Qur''an.', 'Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara.', 'Latihan dasar harus dimulai dari ketelitian mendengar dan menirukan bacaan, bukan terburu-buru mengejar banyak hukum.', 'a', 'Bagian awal ini merapikan pondasi. Santri tidak langsung dibebani istilah cabang, tetapi diajak paham dulu apa itu tajwid, mengapa bacaan harus dijaga, serta bagaimana huruf dan harakat membentuk bunyi yang benar.', 6),
  ('kitab-tajwid-l01-q07', 'kitab-tajwid-l01', 'pilihan_ganda', 'Mana yang benar tentang Level 1?', '["Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara.", "Ilmu tajwid menjaga lisan dari kesalahan membaca Al-Qur''an.", "Latihan dasar harus dimulai dari ketelitian mendengar dan menirukan bacaan, bukan terburu-buru mengejar banyak hukum.", "latihan bunyi huruf yang berdekatan"]', 'Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara.', 'Ilmu tajwid menjaga lisan dari kesalahan membaca Al-Qur''an.', 'Latihan dasar harus dimulai dari ketelitian mendengar dan menirukan bacaan, bukan terburu-buru mengejar banyak hukum.', 'latihan bunyi huruf yang berdekatan', 'b', 'Ilmu tajwid menjaga lisan dari kesalahan membaca Al-Qur''an.', 7),
  ('kitab-tajwid-l01-q08', 'kitab-tajwid-l01', 'pilihan_ganda', 'Kesimpulan yang tepat dari Level 1 adalah?', '["latihan bunyi huruf yang berdekatan", "Latihan dasar harus dimulai dari ketelitian mendengar dan menirukan bacaan, bukan terburu-buru mengejar banyak hukum.", "Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara.", "contoh kata yang menuntut kejelasan bunyi huruf dan harakat"]', 'latihan bunyi huruf yang berdekatan', 'Latihan dasar harus dimulai dari ketelitian mendengar dan menirukan bacaan, bukan terburu-buru mengejar banyak hukum.', 'Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara.', 'contoh kata yang menuntut kejelasan bunyi huruf dan harakat', 'c', 'Pengantar huruf hijaiyah dan harakat membantu santri membedakan bunyi pendek, panjang, dan tempat keluarnya suara.', 8),
  ('kitab-tajwid-l02-q01', 'kitab-tajwid-l02', 'pilihan_ganda', 'Apa arti dari مِنْ آمَنَ?', '["contoh izhar halqi karena nun sukun bertemu hamzah", "contoh idgham bighunnah saat nun sukun bertemu wau", "membaca nun sukun atau tanwin dengan jelas karena bertemu huruf halqi", "memasukkan bunyi nun sukun atau tanwin dengan dengung"]', 'contoh izhar halqi karena nun sukun bertemu hamzah', 'contoh idgham bighunnah saat nun sukun bertemu wau', 'membaca nun sukun atau tanwin dengan jelas karena bertemu huruf halqi', 'memasukkan bunyi nun sukun atau tanwin dengan dengung', 'a', 'مِنْ آمَنَ dalam level ini bermakna: contoh izhar halqi karena nun sukun bertemu hamzah.', 1),
