  ('kitab-tajwid-l04-q04', 'kitab-tajwid-l04', 'pilihan_ganda', 'Mana contoh yang bermakna «contoh mim tasydid yang dibaca dengan ghunnah»?', '["ثُمَّ", "لَهُمْ مَا", "izhar halqi", "idgham bighunnah"]', 'ثُمَّ', 'لَهُمْ مَا', 'izhar halqi', 'idgham bighunnah', 'a', 'Contoh yang tepat adalah ثُمَّ.', 4),
