  ('kitab-aqidah-l04-q05', 'kitab-aqidah-l04', 'pilihan_ganda', 'Istilah «tanzih» artinya?', '["mensucikan Allah dari sifat kekurangan dan penyerupaan dengan makhluk", "Allah Maha Berkuasa", "Allah Maha Mengetahui", "mengesakan Allah dalam keyakinan, ibadah, dan pengagungan"]', 'mensucikan Allah dari sifat kekurangan dan penyerupaan dengan makhluk', 'Allah Maha Berkuasa', 'Allah Maha Mengetahui', 'mengesakan Allah dalam keyakinan, ibadah, dan pengagungan', 'a', 'tanzih berarti mensucikan Allah dari sifat kekurangan dan penyerupaan dengan makhluk.', 5),
  ('kitab-aqidah-l04-q06', 'kitab-aqidah-l04', 'pilihan_ganda', 'Istilah «sifat ma''ani» artinya?', '["Allah Maha Berkuasa", "sifat-sifat kesempurnaan seperti qudrat, iradat, ilmu, hayat, sama'', basar, dan kalam", "Allah Maha Mengetahui", "mengesakan Allah dalam keyakinan, ibadah, dan pengagungan"]', 'Allah Maha Berkuasa', 'sifat-sifat kesempurnaan seperti qudrat, iradat, ilmu, hayat, sama'', basar, dan kalam', 'Allah Maha Mengetahui', 'mengesakan Allah dalam keyakinan, ibadah, dan pengagungan', 'b', 'sifat ma''ani berarti sifat-sifat kesempurnaan seperti qudrat, iradat, ilmu, hayat, sama'', basar, dan kalam.', 6),
  ('kitab-aqidah-l04-q07', 'kitab-aqidah-l04', 'pilihan_ganda', 'Istilah «sifat ma''nawiyyah» artinya?', '["Allah Maha Mengetahui", "Allah Maha Berkuasa", "penegasan bahwa Allah benar-benar bersifat dengan sifat ma''ani tersebut", "mengesakan Allah dalam keyakinan, ibadah, dan pengagungan"]', 'Allah Maha Mengetahui', 'Allah Maha Berkuasa', 'penegasan bahwa Allah benar-benar bersifat dengan sifat ma''ani tersebut', 'mengesakan Allah dalam keyakinan, ibadah, dan pengagungan', 'c', 'sifat ma''nawiyyah berarti penegasan bahwa Allah benar-benar bersifat dengan sifat ma''ani tersebut.', 7),
  ('kitab-aqidah-l04-q08', 'kitab-aqidah-l04', 'pilihan_ganda', 'Fokus utama Level 4 adalah?', '["Sifat ma''nawiyyah membantu santri melihat hubungan antara istilah aqidah dan maknanya.", "Modul ini berfungsi sebagai penguat. Santri diajak memahami bahwa sifat ma''nawiyyah menegaskan konsekuensi dari sifat ma''ani: karena Allah berkuasa, maka pasti Dia Maha Berkuasa; karena Allah berilmu, maka pasti Dia Maha Mengetahui, dan seterusnya.", "Kaunuhu qadiran dan kawan-kawannya, serta menjaga keyakinan agar tidak menyerupakan Allah dengan makhluk.", "Tanzih berarti mensucikan Allah dari bentuk, arah, dan kelemahan makhluk."]', 'Sifat ma''nawiyyah membantu santri melihat hubungan antara istilah aqidah dan maknanya.', 'Modul ini berfungsi sebagai penguat. Santri diajak memahami bahwa sifat ma''nawiyyah menegaskan konsekuensi dari sifat ma''ani: karena Allah berkuasa, maka pasti Dia Maha Berkuasa; karena Allah berilmu, maka pasti Dia Maha Mengetahui, dan seterusnya.', 'Kaunuhu qadiran dan kawan-kawannya, serta menjaga keyakinan agar tidak menyerupakan Allah dengan makhluk.', 'Tanzih berarti mensucikan Allah dari bentuk, arah, dan kelemahan makhluk.', 'c', 'Level ini fokus pada: Kaunuhu qadiran dan kawan-kawannya, serta menjaga keyakinan agar tidak menyerupakan Allah dengan makhluk.', 8),
  ('kitab-aqidah-l05-q01', 'kitab-aqidah-l05', 'pilihan_ganda', 'Apa arti dari الصِّدْقُ?', '["jujur", "menjaga amanah", "mengesakan Allah dalam keyakinan, ibadah, dan pengagungan", "mensucikan Allah dari sifat kekurangan dan penyerupaan dengan makhluk"]', 'jujur', 'menjaga amanah', 'mengesakan Allah dalam keyakinan, ibadah, dan pengagungan', 'mensucikan Allah dari sifat kekurangan dan penyerupaan dengan makhluk', 'a', 'الصِّدْقُ dalam level ini bermakna: jujur.', 1),
