  ('kitab-hadits-l04-q08', 'kitab-hadits-l04', 'pilihan_ganda', 'Kesimpulan yang tepat dari Level 4 adalah?', '["sesungguhnya salah seorang dari kalian dikumpulkan penciptaannya", "Baik buruk penutup amal menjadi peringatan agar istiqamah sampai akhir.", "Pembahasan takdir harus melahirkan tawakal dan kesungguhan, bukan kemalasan.", "sesungguhnya amal itu dinilai pada penutupnya"]', 'sesungguhnya salah seorang dari kalian dikumpulkan penciptaannya', 'Baik buruk penutup amal menjadi peringatan agar istiqamah sampai akhir.', 'Pembahasan takdir harus melahirkan tawakal dan kesungguhan, bukan kemalasan.', 'sesungguhnya amal itu dinilai pada penutupnya', 'c', 'Pembahasan takdir harus melahirkan tawakal dan kesungguhan, bukan kemalasan.', 8),
  ('kitab-hadits-l05-q01', 'kitab-hadits-l05', 'pilihan_ganda', 'Apa arti dari مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ?', '["barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya", "maka ia tertolak", "penjelasan atas matan hadits", "memurnikan amal hanya karena Allah"]', 'barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya', 'maka ia tertolak', 'penjelasan atas matan hadits', 'memurnikan amal hanya karena Allah', 'a', 'مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ dalam level ini bermakna: barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya.', 1),
  ('kitab-hadits-l05-q02', 'kitab-hadits-l05', 'pilihan_ganda', 'Mana contoh yang bermakna «barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya»?', '["ikhlas", "فَهُوَ رَدٌّ", "syarah", "مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ"]', 'ikhlas', 'فَهُوَ رَدٌّ', 'syarah', 'مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ', 'd', 'Contoh yang tepat adalah مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ.', 2),
  ('kitab-hadits-l05-q03', 'kitab-hadits-l05', 'pilihan_ganda', 'Apa arti dari فَهُوَ رَدٌّ?', '["barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya", "maka ia tertolak", "penjelasan atas matan hadits", "memurnikan amal hanya karena Allah"]', 'barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya', 'maka ia tertolak', 'penjelasan atas matan hadits', 'memurnikan amal hanya karena Allah', 'b', 'فَهُوَ رَدٌّ dalam level ini bermakna: maka ia tertolak.', 3),
  ('kitab-hadits-l05-q04', 'kitab-hadits-l05', 'pilihan_ganda', 'Mana contoh yang bermakna «maka ia tertolak»?', '["فَهُوَ رَدٌّ", "مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ", "syarah", "ikhlas"]', 'فَهُوَ رَدٌّ', 'مَنْ أَحْدَثَ فِي أَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ', 'syarah', 'ikhlas', 'a', 'Contoh yang tepat adalah فَهُوَ رَدٌّ.', 4),
  ('kitab-hadits-l05-q05', 'kitab-hadits-l05', 'pilihan_ganda', 'Istilah «bid''ah» artinya?', '["perkara baru dalam urusan agama yang tidak punya landasan syar''i", "barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya", "maka ia tertolak", "penjelasan atas matan hadits"]', 'perkara baru dalam urusan agama yang tidak punya landasan syar''i', 'barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya', 'maka ia tertolak', 'penjelasan atas matan hadits', 'a', 'bid''ah berarti perkara baru dalam urusan agama yang tidak punya landasan syar''i.', 5),
  ('kitab-hadits-l05-q06', 'kitab-hadits-l05', 'pilihan_ganda', 'Fokus utama Level 5 adalah?', '["Agama punya aturan dan tidak dibentuk oleh selera manusia.", "Pembahasan bid''ah dalam PDF menegaskan pentingnya mengikuti tuntunan, bukan membuat ibadah sendiri tanpa landasan. Untuk anak, inti pelajarannya diarahkan ke sikap hati-hati dan cinta terhadap sunnah.", "Hadits tentang tertolaknya perkara baru yang tidak berasal dari agama.", "Semangat beribadah harus disertai ilmu agar tidak jatuh pada penyimpangan."]', 'Agama punya aturan dan tidak dibentuk oleh selera manusia.', 'Pembahasan bid''ah dalam PDF menegaskan pentingnya mengikuti tuntunan, bukan membuat ibadah sendiri tanpa landasan. Untuk anak, inti pelajarannya diarahkan ke sikap hati-hati dan cinta terhadap sunnah.', 'Hadits tentang tertolaknya perkara baru yang tidak berasal dari agama.', 'Semangat beribadah harus disertai ilmu agar tidak jatuh pada penyimpangan.', 'c', 'Level ini fokus pada: Hadits tentang tertolaknya perkara baru yang tidak berasal dari agama.', 6),
  ('kitab-hadits-l05-q07', 'kitab-hadits-l05', 'pilihan_ganda', 'Pilih pernyataan yang paling tepat dari pelajaran ini.', '["Pembahasan bid''ah dalam PDF menegaskan pentingnya mengikuti tuntunan, bukan membuat ibadah sendiri tanpa landasan. Untuk anak, inti pelajarannya diarahkan ke sikap hati-hati dan cinta terhadap sunnah.", "Agama punya aturan dan tidak dibentuk oleh selera manusia.", "Semangat beribadah harus disertai ilmu agar tidak jatuh pada penyimpangan.", "Mengikuti sunnah berarti memilih jalan yang aman dan dicintai Allah."]', 'Pembahasan bid''ah dalam PDF menegaskan pentingnya mengikuti tuntunan, bukan membuat ibadah sendiri tanpa landasan. Untuk anak, inti pelajarannya diarahkan ke sikap hati-hati dan cinta terhadap sunnah.', 'Agama punya aturan dan tidak dibentuk oleh selera manusia.', 'Semangat beribadah harus disertai ilmu agar tidak jatuh pada penyimpangan.', 'Mengikuti sunnah berarti memilih jalan yang aman dan dicintai Allah.', 'a', 'Pembahasan bid''ah dalam PDF menegaskan pentingnya mengikuti tuntunan, bukan membuat ibadah sendiri tanpa landasan. Untuk anak, inti pelajarannya diarahkan ke sikap hati-hati dan cinta terhadap sunnah.', 7),
  ('kitab-hadits-l05-q08', 'kitab-hadits-l05', 'pilihan_ganda', 'Mana yang benar tentang Level 5?', '["Semangat beribadah harus disertai ilmu agar tidak jatuh pada penyimpangan.", "Agama punya aturan dan tidak dibentuk oleh selera manusia.", "Mengikuti sunnah berarti memilih jalan yang aman dan dicintai Allah.", "barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya"]', 'Semangat beribadah harus disertai ilmu agar tidak jatuh pada penyimpangan.', 'Agama punya aturan dan tidak dibentuk oleh selera manusia.', 'Mengikuti sunnah berarti memilih jalan yang aman dan dicintai Allah.', 'barangsiapa mengadakan perkara baru dalam urusan kami ini yang bukan darinya', 'b', 'Agama punya aturan dan tidak dibentuk oleh selera manusia.', 8),
  ('kitab-hadits-l06-q01', 'kitab-hadits-l06', 'pilihan_ganda', 'Apa arti dari إِنَّ الْحَلَالَ بَيِّنٌ وَإِنَّ الْحَرَامَ بَيِّنٌ?', '["yang halal itu jelas dan yang haram itu jelas", "tinggalkan apa yang meragukanmu", "penjelasan atas matan hadits", "memurnikan amal hanya karena Allah"]', 'yang halal itu jelas dan yang haram itu jelas', 'tinggalkan apa yang meragukanmu', 'penjelasan atas matan hadits', 'memurnikan amal hanya karena Allah', 'a', 'إِنَّ الْحَلَالَ بَيِّنٌ وَإِنَّ الْحَرَامَ بَيِّنٌ dalam level ini bermakna: yang halal itu jelas dan yang haram itu jelas.', 1),
