  ('kitab-adab-l02-q05', 'kitab-adab-l02', 'pilihan_ganda', 'Istilah «hidayah» artinya?', '["petunjuk Allah yang mengarahkan hati dan amal", "segala puji bagi Allah yang menghidupkan kami", "aku memohon ampunan-Mu", "mengevaluasi diri dan amal secara jujur"]', 'petunjuk Allah yang mengarahkan hati dan amal', 'segala puji bagi Allah yang menghidupkan kami', 'aku memohon ampunan-Mu', 'mengevaluasi diri dan amal secara jujur', 'a', 'hidayah berarti petunjuk Allah yang mengarahkan hati dan amal.', 5),
  ('kitab-adab-l02-q06', 'kitab-adab-l02', 'pilihan_ganda', 'Istilah «adab» artinya?', '["segala puji bagi Allah yang menghidupkan kami", "perilaku yang tepat, sopan, dan sesuai tuntunan", "aku memohon ampunan-Mu", "petunjuk Allah yang mengarahkan hati dan amal"]', 'segala puji bagi Allah yang menghidupkan kami', 'perilaku yang tepat, sopan, dan sesuai tuntunan', 'aku memohon ampunan-Mu', 'petunjuk Allah yang mengarahkan hati dan amal', 'b', 'adab berarti perilaku yang tepat, sopan, dan sesuai tuntunan.', 6),
  ('kitab-adab-l02-q07', 'kitab-adab-l02', 'pilihan_ganda', 'Istilah «dzikir» artinya?', '["aku memohon ampunan-Mu", "segala puji bagi Allah yang menghidupkan kami", "mengingat Allah dengan lisan dan hati", "petunjuk Allah yang mengarahkan hati dan amal"]', 'aku memohon ampunan-Mu', 'segala puji bagi Allah yang menghidupkan kami', 'mengingat Allah dengan lisan dan hati', 'petunjuk Allah yang mengarahkan hati dan amal', 'c', 'dzikir berarti mengingat Allah dengan lisan dan hati.', 7),
  ('kitab-adab-l02-q08', 'kitab-adab-l02', 'pilihan_ganda', 'Fokus utama Level 2 adalah?', '["Pagi hari menentukan arah batin dan kebiasaan sepanjang hari.", "Bab perintah Allah dalam kitab ini dimulai dari hal yang sangat kecil tetapi sering diabaikan. Justru di situlah letak kekuatan kitab: hidayah dibangun dari kebiasaan harian yang disiplin sejak membuka mata.", "Rutinitas pagi: doa bangun tidur, adab masuk kamar kecil, istinja, dan siwak.", "Adab kamar kecil dan istinja melatih rasa malu, kebersihan, dan kesadaran syariat."]', 'Pagi hari menentukan arah batin dan kebiasaan sepanjang hari.', 'Bab perintah Allah dalam kitab ini dimulai dari hal yang sangat kecil tetapi sering diabaikan. Justru di situlah letak kekuatan kitab: hidayah dibangun dari kebiasaan harian yang disiplin sejak membuka mata.', 'Rutinitas pagi: doa bangun tidur, adab masuk kamar kecil, istinja, dan siwak.', 'Adab kamar kecil dan istinja melatih rasa malu, kebersihan, dan kesadaran syariat.', 'c', 'Level ini fokus pada: Rutinitas pagi: doa bangun tidur, adab masuk kamar kecil, istinja, dan siwak.', 8),
  ('kitab-adab-l03-q01', 'kitab-adab-l03', 'pilihan_ganda', 'Apa arti dari بِسْمِ اللّٰهِ?', '["dengan nama Allah", "ya Allah jadikan aku termasuk orang yang bertobat", "petunjuk Allah yang mengarahkan hati dan amal", "mengevaluasi diri dan amal secara jujur"]', 'dengan nama Allah', 'ya Allah jadikan aku termasuk orang yang bertobat', 'petunjuk Allah yang mengarahkan hati dan amal', 'mengevaluasi diri dan amal secara jujur', 'a', 'بِسْمِ اللّٰهِ dalam level ini bermakna: dengan nama Allah.', 1),
  ('kitab-adab-l03-q02', 'kitab-adab-l03', 'pilihan_ganda', 'Mana contoh yang bermakna «dengan nama Allah»?', '["muhasabah", "اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ", "hidayah", "بِسْمِ اللّٰهِ"]', 'muhasabah', 'اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ', 'hidayah', 'بِسْمِ اللّٰهِ', 'd', 'Contoh yang tepat adalah بِسْمِ اللّٰهِ.', 2),
  ('kitab-adab-l03-q03', 'kitab-adab-l03', 'pilihan_ganda', 'Apa arti dari اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ?', '["dengan nama Allah", "ya Allah jadikan aku termasuk orang yang bertobat", "petunjuk Allah yang mengarahkan hati dan amal", "mengevaluasi diri dan amal secara jujur"]', 'dengan nama Allah', 'ya Allah jadikan aku termasuk orang yang bertobat', 'petunjuk Allah yang mengarahkan hati dan amal', 'mengevaluasi diri dan amal secara jujur', 'b', 'اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ dalam level ini bermakna: ya Allah jadikan aku termasuk orang yang bertobat.', 3),
  ('kitab-adab-l03-q04', 'kitab-adab-l03', 'pilihan_ganda', 'Mana contoh yang bermakna «ya Allah jadikan aku termasuk orang yang bertobat»?', '["اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ", "بِسْمِ اللّٰهِ", "hidayah", "muhasabah"]', 'اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ', 'بِسْمِ اللّٰهِ', 'hidayah', 'muhasabah', 'a', 'Contoh yang tepat adalah اللّٰهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ.', 4),
  ('kitab-adab-l03-q05', 'kitab-adab-l03', 'pilihan_ganda', 'Istilah «adab» artinya?', '["perilaku yang tepat, sopan, dan sesuai tuntunan", "dengan nama Allah", "ya Allah jadikan aku termasuk orang yang bertobat", "petunjuk Allah yang mengarahkan hati dan amal"]', 'perilaku yang tepat, sopan, dan sesuai tuntunan', 'dengan nama Allah', 'ya Allah jadikan aku termasuk orang yang bertobat', 'petunjuk Allah yang mengarahkan hati dan amal', 'a', 'adab berarti perilaku yang tepat, sopan, dan sesuai tuntunan.', 5),
  ('kitab-adab-l03-q06', 'kitab-adab-l03', 'pilihan_ganda', 'Fokus utama Level 3 adalah?', '["Bersuci adalah bentuk ketaatan, bukan rutinitas mekanis belaka.", "Pada bagian ini, kitab mengajarkan bahwa ibadah lahir menuntut kesiapan lahir juga. Wudhu, mandi, dan tayammum tidak hanya dibahas secara hukum, tetapi juga dengan rasa adab dan kehadiran hati.", "Adab bersuci yang detail sebagai pintu semua ibadah.", "Doa-doa saat wudhu membantu hati tetap sadar ketika anggota badan dibasuh."]', 'Bersuci adalah bentuk ketaatan, bukan rutinitas mekanis belaka.', 'Pada bagian ini, kitab mengajarkan bahwa ibadah lahir menuntut kesiapan lahir juga. Wudhu, mandi, dan tayammum tidak hanya dibahas secara hukum, tetapi juga dengan rasa adab dan kehadiran hati.', 'Adab bersuci yang detail sebagai pintu semua ibadah.', 'Doa-doa saat wudhu membantu hati tetap sadar ketika anggota badan dibasuh.', 'c', 'Level ini fokus pada: Adab bersuci yang detail sebagai pintu semua ibadah.', 6),
  ('kitab-adab-l03-q07', 'kitab-adab-l03', 'pilihan_ganda', 'Pilih pernyataan yang paling tepat dari pelajaran ini.', '["Pada bagian ini, kitab mengajarkan bahwa ibadah lahir menuntut kesiapan lahir juga. Wudhu, mandi, dan tayammum tidak hanya dibahas secara hukum, tetapi juga dengan rasa adab dan kehadiran hati.", "Bersuci adalah bentuk ketaatan, bukan rutinitas mekanis belaka.", "Doa-doa saat wudhu membantu hati tetap sadar ketika anggota badan dibasuh.", "Tayammum mengajarkan bahwa syariat punya kemudahan tanpa kehilangan kehormatan."]', 'Pada bagian ini, kitab mengajarkan bahwa ibadah lahir menuntut kesiapan lahir juga. Wudhu, mandi, dan tayammum tidak hanya dibahas secara hukum, tetapi juga dengan rasa adab dan kehadiran hati.', 'Bersuci adalah bentuk ketaatan, bukan rutinitas mekanis belaka.', 'Doa-doa saat wudhu membantu hati tetap sadar ketika anggota badan dibasuh.', 'Tayammum mengajarkan bahwa syariat punya kemudahan tanpa kehilangan kehormatan.', 'a', 'Pada bagian ini, kitab mengajarkan bahwa ibadah lahir menuntut kesiapan lahir juga. Wudhu, mandi, dan tayammum tidak hanya dibahas secara hukum, tetapi juga dengan rasa adab dan kehadiran hati.', 7),
  ('kitab-adab-l03-q08', 'kitab-adab-l03', 'pilihan_ganda', 'Mana yang benar tentang Level 3?', '["Doa-doa saat wudhu membantu hati tetap sadar ketika anggota badan dibasuh.", "Bersuci adalah bentuk ketaatan, bukan rutinitas mekanis belaka.", "Tayammum mengajarkan bahwa syariat punya kemudahan tanpa kehilangan kehormatan.", "dengan nama Allah"]', 'Doa-doa saat wudhu membantu hati tetap sadar ketika anggota badan dibasuh.', 'Bersuci adalah bentuk ketaatan, bukan rutinitas mekanis belaka.', 'Tayammum mengajarkan bahwa syariat punya kemudahan tanpa kehilangan kehormatan.', 'dengan nama Allah', 'b', 'Bersuci adalah bentuk ketaatan, bukan rutinitas mekanis belaka.', 8),
  ('kitab-adab-l04-q01', 'kitab-adab-l04', 'pilihan_ganda', 'Apa arti dari إِلَى الْمَسْجِدِ?', '["menuju masjid untuk ibadah", "Allah Mahabesar sebagai pintu masuk shalat", "petunjuk Allah yang mengarahkan hati dan amal", "mengevaluasi diri dan amal secara jujur"]', 'menuju masjid untuk ibadah', 'Allah Mahabesar sebagai pintu masuk shalat', 'petunjuk Allah yang mengarahkan hati dan amal', 'mengevaluasi diri dan amal secara jujur', 'a', 'إِلَى الْمَسْجِدِ dalam level ini bermakna: menuju masjid untuk ibadah.', 1),
